import java.util.TreeMap;

public class Main {
    public static void main(String[] args) {
        String[] names = {"Asha", "Ravi", "Asha", "Ravi"};
        int[] scores = {85, 72, 60, 90};
        TreeMap<String, Integer> best = new TreeMap<>();
        for (int i = 0; i < names.length; i++) {
            best.put(names[i], Math.max(best.getOrDefault(names[i], 0), scores[i]));
        }
        System.out.println(best);
    }
}
